CREATE TABLE collections (
  id TEXT NOT NULL CHECK (id IS NULL OR (length(id)=36 AND length(CAST(id AS BLOB))=36 AND substr(id,9,1)='-' AND substr(id,14,1)='-' AND substr(id,19,1)='-' AND substr(id,24,1)='-' AND length(replace(id,'-',''))=32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*')),
  kind TEXT NOT NULL CHECK (kind IS NULL OR length(kind)>0),
  reporter TEXT NOT NULL CHECK (reporter IS NULL OR length(reporter)>0),
  reporter_version TEXT NOT NULL CHECK (reporter_version IS NULL OR length(reporter_version)>0),
  reporter_context_id TEXT NOT NULL CHECK (reporter_context_id IS NULL OR (length(reporter_context_id)=36 AND length(CAST(reporter_context_id AS BLOB))=36 AND substr(reporter_context_id,9,1)='-' AND substr(reporter_context_id,14,1)='-' AND substr(reporter_context_id,19,1)='-' AND substr(reporter_context_id,24,1)='-' AND length(replace(reporter_context_id,'-',''))=32 AND replace(reporter_context_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES contexts(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  interpretation_rule_id TEXT NOT NULL CHECK (interpretation_rule_id IS NULL OR (length(interpretation_rule_id)=36 AND length(CAST(interpretation_rule_id AS BLOB))=36 AND substr(interpretation_rule_id,9,1)='-' AND substr(interpretation_rule_id,14,1)='-' AND substr(interpretation_rule_id,19,1)='-' AND substr(interpretation_rule_id,24,1)='-' AND length(replace(interpretation_rule_id,'-',''))=32 AND replace(interpretation_rule_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES rule_versions(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  started_at INTEGER NOT NULL,
  request_protocol TEXT NOT NULL CHECK (request_protocol IS NULL OR length(request_protocol)>0),
  request_digest BLOB NOT NULL CHECK (length(request_digest)=32),
  PRIMARY KEY (id),
  CHECK (kind IN ('discovery','manual')),
  CHECK (request_protocol='koine.request.v1')
) STRICT;

CREATE INDEX collections_reporter_context_id_fk ON collections(reporter_context_id);

CREATE INDEX collections_interpretation_rule_id_fk ON collections(interpretation_rule_id);

