CREATE TABLE coverage_results (
  id TEXT NOT NULL CHECK (id IS NULL OR (length(id)=36 AND length(CAST(id AS BLOB))=36 AND substr(id,9,1)='-' AND substr(id,14,1)='-' AND substr(id,19,1)='-' AND substr(id,24,1)='-' AND length(replace(id,'-',''))=32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*')),
  unit_id TEXT NOT NULL CHECK (unit_id IS NULL OR (length(unit_id)=36 AND length(CAST(unit_id AS BLOB))=36 AND substr(unit_id,9,1)='-' AND substr(unit_id,14,1)='-' AND substr(unit_id,19,1)='-' AND substr(unit_id,24,1)='-' AND length(replace(unit_id,'-',''))=32 AND replace(unit_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES requested_units(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  collection_id TEXT NOT NULL CHECK (collection_id IS NULL OR (length(collection_id)=36 AND length(CAST(collection_id AS BLOB))=36 AND substr(collection_id,9,1)='-' AND substr(collection_id,14,1)='-' AND substr(collection_id,19,1)='-' AND substr(collection_id,24,1)='-' AND length(replace(collection_id,'-',''))=32 AND replace(collection_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES collections(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  dimension TEXT NOT NULL CHECK (dimension IS NULL OR length(dimension)>0),
  authority_scope_id TEXT NOT NULL CHECK (authority_scope_id IS NULL OR (length(authority_scope_id)=36 AND length(CAST(authority_scope_id AS BLOB))=36 AND substr(authority_scope_id,9,1)='-' AND substr(authority_scope_id,14,1)='-' AND substr(authority_scope_id,19,1)='-' AND substr(authority_scope_id,24,1)='-' AND length(replace(authority_scope_id,'-',''))=32 AND replace(authority_scope_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES authority_scopes(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  outcome TEXT NOT NULL CHECK (outcome IS NULL OR length(outcome)>0),
  reason TEXT CHECK (reason IS NULL OR length(reason)>0),
  PRIMARY KEY (id),
  UNIQUE (unit_id),
  UNIQUE (id,collection_id,unit_id,dimension,authority_scope_id),
  CHECK (outcome IN ('complete','partial','failed','inconclusive')),
  CHECK (outcome='complete' OR reason IS NOT NULL),
  FOREIGN KEY (unit_id,collection_id,dimension,authority_scope_id) REFERENCES requested_units(id,collection_id,dimension,authority_scope_id) ON UPDATE RESTRICT ON DELETE RESTRICT
) STRICT;

CREATE INDEX coverage_results_unit_id_fk ON coverage_results(unit_id);

CREATE INDEX coverage_results_collection_id_fk ON coverage_results(collection_id);

CREATE INDEX coverage_results_authority_scope_id_fk ON coverage_results(authority_scope_id);

CREATE INDEX coverage_results_composite_0_fk ON coverage_results(unit_id,collection_id,dimension,authority_scope_id);

CREATE TRIGGER coverage_results_immutable_update BEFORE UPDATE ON coverage_results BEGIN SELECT RAISE(ABORT,'immutable record'); END;

CREATE TRIGGER coverage_results_immutable_delete BEFORE DELETE ON coverage_results BEGIN SELECT RAISE(ABORT,'immutable record'); END;

CREATE TRIGGER coverage_results_duplicate BEFORE INSERT ON coverage_results WHEN EXISTS(SELECT 1 FROM coverage_results WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'duplicate immutable identity'); END;

CREATE TABLE coverage_parts (
  id TEXT NOT NULL CHECK (id IS NULL OR (length(id)=36 AND length(CAST(id AS BLOB))=36 AND substr(id,9,1)='-' AND substr(id,14,1)='-' AND substr(id,19,1)='-' AND substr(id,24,1)='-' AND length(replace(id,'-',''))=32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*')),
  coverage_id TEXT NOT NULL CHECK (coverage_id IS NULL OR (length(coverage_id)=36 AND length(CAST(coverage_id AS BLOB))=36 AND substr(coverage_id,9,1)='-' AND substr(coverage_id,14,1)='-' AND substr(coverage_id,19,1)='-' AND substr(coverage_id,24,1)='-' AND length(replace(coverage_id,'-',''))=32 AND replace(coverage_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES coverage_results(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  collection_id TEXT NOT NULL CHECK (collection_id IS NULL OR (length(collection_id)=36 AND length(CAST(collection_id AS BLOB))=36 AND substr(collection_id,9,1)='-' AND substr(collection_id,14,1)='-' AND substr(collection_id,19,1)='-' AND substr(collection_id,24,1)='-' AND length(replace(collection_id,'-',''))=32 AND replace(collection_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES collections(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  unit_id TEXT NOT NULL CHECK (unit_id IS NULL OR (length(unit_id)=36 AND length(CAST(unit_id AS BLOB))=36 AND substr(unit_id,9,1)='-' AND substr(unit_id,14,1)='-' AND substr(unit_id,19,1)='-' AND substr(unit_id,24,1)='-' AND length(replace(unit_id,'-',''))=32 AND replace(unit_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES requested_units(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  dimension TEXT NOT NULL CHECK (dimension IS NULL OR length(dimension)>0),
  authority_scope_id TEXT NOT NULL CHECK (authority_scope_id IS NULL OR (length(authority_scope_id)=36 AND length(CAST(authority_scope_id AS BLOB))=36 AND substr(authority_scope_id,9,1)='-' AND substr(authority_scope_id,14,1)='-' AND substr(authority_scope_id,19,1)='-' AND substr(authority_scope_id,24,1)='-' AND length(replace(authority_scope_id,'-',''))=32 AND replace(authority_scope_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES authority_scopes(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  part_key TEXT NOT NULL CHECK (part_key IS NULL OR length(part_key)>0),
  parent_part_id TEXT CHECK (parent_part_id IS NULL OR (length(parent_part_id)=36 AND length(CAST(parent_part_id AS BLOB))=36 AND substr(parent_part_id,9,1)='-' AND substr(parent_part_id,14,1)='-' AND substr(parent_part_id,19,1)='-' AND substr(parent_part_id,24,1)='-' AND length(replace(parent_part_id,'-',''))=32 AND replace(parent_part_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES coverage_parts(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  selector_kind TEXT NOT NULL CHECK (selector_kind IS NULL OR length(selector_kind)>0),
  selector BLOB,
  selector_rule_id TEXT CHECK (selector_rule_id IS NULL OR (length(selector_rule_id)=36 AND length(CAST(selector_rule_id AS BLOB))=36 AND substr(selector_rule_id,9,1)='-' AND substr(selector_rule_id,14,1)='-' AND substr(selector_rule_id,19,1)='-' AND substr(selector_rule_id,24,1)='-' AND length(replace(selector_rule_id,'-',''))=32 AND replace(selector_rule_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES rule_versions(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  inspection TEXT NOT NULL CHECK (inspection IS NULL OR length(inspection)>0),
  outcome TEXT NOT NULL CHECK (outcome IS NULL OR length(outcome)>0),
  reason TEXT CHECK (reason IS NULL OR length(reason)>0),
  PRIMARY KEY (id),
  UNIQUE (coverage_id,part_key),
  UNIQUE (id,collection_id),
  UNIQUE (id,collection_id,dimension,authority_scope_id),
  UNIQUE (id,coverage_id,collection_id,unit_id,dimension,authority_scope_id),
  UNIQUE (id,collection_id,outcome,dimension,authority_scope_id),
  CHECK (outcome IN ('complete','partial','failed','inconclusive')),
  CHECK (outcome='complete' OR reason IS NOT NULL),
  CHECK (parent_part_id IS NULL OR parent_part_id != id),
  CHECK ((parent_part_id IS NULL AND selector_kind='whole_unit' AND selector IS NULL AND selector_rule_id IS NULL) OR (parent_part_id IS NOT NULL AND selector_kind IN ('bounded','residual') AND selector IS NOT NULL AND selector_rule_id IS NOT NULL)),
  CHECK (inspection IN ('inspected','uninspected','mixed','unknown')),
  CHECK ((outcome!='complete' OR inspection='inspected') AND (inspection NOT IN ('uninspected','unknown') OR outcome IN ('failed','inconclusive')) AND (inspection!='mixed' OR outcome!='complete')),
  FOREIGN KEY (coverage_id,collection_id,unit_id,dimension,authority_scope_id) REFERENCES coverage_results(id,collection_id,unit_id,dimension,authority_scope_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  FOREIGN KEY (parent_part_id,coverage_id,collection_id,unit_id,dimension,authority_scope_id) REFERENCES coverage_parts(id,coverage_id,collection_id,unit_id,dimension,authority_scope_id) ON UPDATE RESTRICT ON DELETE RESTRICT
) STRICT;

CREATE INDEX coverage_parts_coverage_id_fk ON coverage_parts(coverage_id);

CREATE INDEX coverage_parts_collection_id_fk ON coverage_parts(collection_id);

CREATE INDEX coverage_parts_unit_id_fk ON coverage_parts(unit_id);

CREATE INDEX coverage_parts_authority_scope_id_fk ON coverage_parts(authority_scope_id);

CREATE INDEX coverage_parts_parent_part_id_fk ON coverage_parts(parent_part_id);

CREATE INDEX coverage_parts_selector_rule_id_fk ON coverage_parts(selector_rule_id);

CREATE INDEX coverage_parts_composite_0_fk ON coverage_parts(coverage_id,collection_id,unit_id,dimension,authority_scope_id);

CREATE INDEX coverage_parts_composite_1_fk ON coverage_parts(parent_part_id,coverage_id,collection_id,unit_id,dimension,authority_scope_id);

CREATE TRIGGER coverage_parts_immutable_update BEFORE UPDATE ON coverage_parts BEGIN SELECT RAISE(ABORT,'immutable record'); END;

CREATE TRIGGER coverage_parts_immutable_delete BEFORE DELETE ON coverage_parts BEGIN SELECT RAISE(ABORT,'immutable record'); END;

CREATE TRIGGER coverage_parts_duplicate BEFORE INSERT ON coverage_parts WHEN EXISTS(SELECT 1 FROM coverage_parts WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'duplicate immutable identity'); END;

CREATE TABLE collection_closures (
  collection_id TEXT NOT NULL CHECK (collection_id IS NULL OR (length(collection_id)=36 AND length(CAST(collection_id AS BLOB))=36 AND substr(collection_id,9,1)='-' AND substr(collection_id,14,1)='-' AND substr(collection_id,19,1)='-' AND substr(collection_id,24,1)='-' AND length(replace(collection_id,'-',''))=32 AND replace(collection_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES collections(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  outcome TEXT NOT NULL CHECK (outcome IS NULL OR length(outcome)>0),
  finished_at INTEGER NOT NULL,
  reason TEXT CHECK (reason IS NULL OR length(reason)>0),
  result_protocol TEXT NOT NULL CHECK (result_protocol IS NULL OR length(result_protocol)>0),
  result_digest BLOB NOT NULL CHECK (length(result_digest)=32),
  PRIMARY KEY (collection_id),
  CHECK (outcome IN ('complete','partial','failed','inconclusive')),
  CHECK (outcome='complete' OR reason IS NOT NULL),
  CHECK (result_protocol='koine.result.v1')
) STRICT;

CREATE INDEX collection_closures_collection_id_fk ON collection_closures(collection_id);

CREATE TRIGGER collection_closures_immutable_update BEFORE UPDATE ON collection_closures BEGIN SELECT RAISE(ABORT,'immutable record'); END;

CREATE TRIGGER collection_closures_immutable_delete BEFORE DELETE ON collection_closures BEGIN SELECT RAISE(ABORT,'immutable record'); END;

CREATE TRIGGER collection_closures_duplicate BEFORE INSERT ON collection_closures WHEN EXISTS(SELECT 1 FROM collection_closures WHERE collection_id=NEW.collection_id) BEGIN SELECT RAISE(ABORT,'duplicate immutable identity'); END;

CREATE TABLE evidence_records (
  id TEXT NOT NULL CHECK (id IS NULL OR (length(id)=36 AND length(CAST(id AS BLOB))=36 AND substr(id,9,1)='-' AND substr(id,14,1)='-' AND substr(id,19,1)='-' AND substr(id,24,1)='-' AND length(replace(id,'-',''))=32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*')),
  collection_id TEXT NOT NULL CHECK (collection_id IS NULL OR (length(collection_id)=36 AND length(CAST(collection_id AS BLOB))=36 AND substr(collection_id,9,1)='-' AND substr(collection_id,14,1)='-' AND substr(collection_id,19,1)='-' AND substr(collection_id,24,1)='-' AND length(replace(collection_id,'-',''))=32 AND replace(collection_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES collections(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  origin_kind TEXT NOT NULL CHECK (origin_kind IS NULL OR length(origin_kind)>0),
  origin_namespace TEXT NOT NULL CHECK (origin_namespace IS NULL OR length(origin_namespace)>0),
  locator_kind TEXT NOT NULL CHECK (locator_kind IS NULL OR length(locator_kind)>0),
  locator BLOB,
  collected_at INTEGER NOT NULL,
  source_effective_at INTEGER,
  source_revision TEXT CHECK (source_revision IS NULL OR length(source_revision)>0),
  valid_until INTEGER,
  interpretation_rule_id TEXT NOT NULL CHECK (interpretation_rule_id IS NULL OR (length(interpretation_rule_id)=36 AND length(CAST(interpretation_rule_id AS BLOB))=36 AND substr(interpretation_rule_id,9,1)='-' AND substr(interpretation_rule_id,14,1)='-' AND substr(interpretation_rule_id,19,1)='-' AND substr(interpretation_rule_id,24,1)='-' AND length(replace(interpretation_rule_id,'-',''))=32 AND replace(interpretation_rule_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES rule_versions(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  item_key TEXT NOT NULL CHECK (item_key IS NULL OR length(item_key)>0),
  PRIMARY KEY (id),
  UNIQUE (collection_id,item_key),
  UNIQUE (id,collection_id),
  CHECK (origin_kind IN ('external','user_assertion')),
  CHECK (locator_kind IN ('path','opaque','unavailable')),
  CHECK ((locator_kind='unavailable' AND locator IS NULL) OR (locator_kind!='unavailable' AND locator IS NOT NULL))
) STRICT;

CREATE INDEX evidence_records_collection_id_fk ON evidence_records(collection_id);

CREATE INDEX evidence_records_interpretation_rule_id_fk ON evidence_records(interpretation_rule_id);

CREATE TRIGGER evidence_records_immutable_update BEFORE UPDATE ON evidence_records BEGIN SELECT RAISE(ABORT,'immutable record'); END;

CREATE TRIGGER evidence_records_immutable_delete BEFORE DELETE ON evidence_records BEGIN SELECT RAISE(ABORT,'immutable record'); END;

CREATE TRIGGER evidence_records_duplicate BEFORE INSERT ON evidence_records WHEN EXISTS(SELECT 1 FROM evidence_records WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'duplicate immutable identity'); END;

CREATE TABLE diagnostics (
  id TEXT NOT NULL CHECK (id IS NULL OR (length(id)=36 AND length(CAST(id AS BLOB))=36 AND substr(id,9,1)='-' AND substr(id,14,1)='-' AND substr(id,19,1)='-' AND substr(id,24,1)='-' AND length(replace(id,'-',''))=32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*')),
  collection_id TEXT NOT NULL CHECK (collection_id IS NULL OR (length(collection_id)=36 AND length(CAST(collection_id AS BLOB))=36 AND substr(collection_id,9,1)='-' AND substr(collection_id,14,1)='-' AND substr(collection_id,19,1)='-' AND substr(collection_id,24,1)='-' AND length(replace(collection_id,'-',''))=32 AND replace(collection_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES collections(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  item_key TEXT NOT NULL CHECK (item_key IS NULL OR length(item_key)>0),
  target_kind TEXT NOT NULL CHECK (target_kind IS NULL OR length(target_kind)>0),
  unit_id TEXT CHECK (unit_id IS NULL OR (length(unit_id)=36 AND length(CAST(unit_id AS BLOB))=36 AND substr(unit_id,9,1)='-' AND substr(unit_id,14,1)='-' AND substr(unit_id,19,1)='-' AND substr(unit_id,24,1)='-' AND length(replace(unit_id,'-',''))=32 AND replace(unit_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES requested_units(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  coverage_part_id TEXT CHECK (coverage_part_id IS NULL OR (length(coverage_part_id)=36 AND length(CAST(coverage_part_id AS BLOB))=36 AND substr(coverage_part_id,9,1)='-' AND substr(coverage_part_id,14,1)='-' AND substr(coverage_part_id,19,1)='-' AND substr(coverage_part_id,24,1)='-' AND length(replace(coverage_part_id,'-',''))=32 AND replace(coverage_part_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES coverage_parts(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  evidence_id TEXT CHECK (evidence_id IS NULL OR (length(evidence_id)=36 AND length(CAST(evidence_id AS BLOB))=36 AND substr(evidence_id,9,1)='-' AND substr(evidence_id,14,1)='-' AND substr(evidence_id,19,1)='-' AND substr(evidence_id,24,1)='-' AND length(replace(evidence_id,'-',''))=32 AND replace(evidence_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES evidence_records(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  key_observation_id TEXT CHECK (key_observation_id IS NULL OR (length(key_observation_id)=36 AND length(CAST(key_observation_id AS BLOB))=36 AND substr(key_observation_id,9,1)='-' AND substr(key_observation_id,14,1)='-' AND substr(key_observation_id,19,1)='-' AND substr(key_observation_id,24,1)='-' AND length(replace(key_observation_id,'-',''))=32 AND replace(key_observation_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES entry_key_observations(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  claim_id TEXT CHECK (claim_id IS NULL OR (length(claim_id)=36 AND length(CAST(claim_id AS BLOB))=36 AND substr(claim_id,9,1)='-' AND substr(claim_id,14,1)='-' AND substr(claim_id,19,1)='-' AND substr(claim_id,24,1)='-' AND length(replace(claim_id,'-',''))=32 AND replace(claim_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES claims(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  severity TEXT NOT NULL CHECK (severity IS NULL OR length(severity)>0),
  code TEXT NOT NULL CHECK (code IS NULL OR length(code)>0),
  message TEXT NOT NULL CHECK (message IS NULL OR length(message)>0),
  affected_dimension TEXT CHECK (affected_dimension IS NULL OR length(affected_dimension)>0),
  recorded_at INTEGER NOT NULL,
  PRIMARY KEY (id),
  UNIQUE (collection_id,item_key),
  CHECK (severity IN ('info','warning','error')),
  CHECK ((target_kind='collection' AND unit_id IS NULL AND coverage_part_id IS NULL AND evidence_id IS NULL AND key_observation_id IS NULL AND claim_id IS NULL) OR (target_kind='unit' AND unit_id IS NOT NULL AND coverage_part_id IS NULL AND evidence_id IS NULL AND key_observation_id IS NULL AND claim_id IS NULL) OR (target_kind='coverage_part' AND unit_id IS NULL AND coverage_part_id IS NOT NULL AND evidence_id IS NULL AND key_observation_id IS NULL AND claim_id IS NULL) OR (target_kind='evidence' AND unit_id IS NULL AND coverage_part_id IS NULL AND evidence_id IS NOT NULL AND key_observation_id IS NULL AND claim_id IS NULL) OR (target_kind='key_observation' AND unit_id IS NULL AND coverage_part_id IS NULL AND evidence_id IS NULL AND key_observation_id IS NOT NULL AND claim_id IS NULL) OR (target_kind='claim' AND unit_id IS NULL AND coverage_part_id IS NULL AND evidence_id IS NULL AND key_observation_id IS NULL AND claim_id IS NOT NULL)),
  FOREIGN KEY (unit_id,collection_id) REFERENCES requested_units(id,collection_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  FOREIGN KEY (coverage_part_id,collection_id) REFERENCES coverage_parts(id,collection_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  FOREIGN KEY (evidence_id,collection_id) REFERENCES evidence_records(id,collection_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  FOREIGN KEY (key_observation_id,collection_id) REFERENCES entry_key_observations(id,collection_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  FOREIGN KEY (claim_id,collection_id) REFERENCES claims(id,collection_id) ON UPDATE RESTRICT ON DELETE RESTRICT
) STRICT;

CREATE INDEX diagnostics_collection_id_fk ON diagnostics(collection_id);

CREATE INDEX diagnostics_unit_id_fk ON diagnostics(unit_id);

CREATE INDEX diagnostics_coverage_part_id_fk ON diagnostics(coverage_part_id);

CREATE INDEX diagnostics_evidence_id_fk ON diagnostics(evidence_id);

CREATE INDEX diagnostics_key_observation_id_fk ON diagnostics(key_observation_id);

CREATE INDEX diagnostics_claim_id_fk ON diagnostics(claim_id);

CREATE INDEX diagnostics_composite_0_fk ON diagnostics(unit_id,collection_id);

CREATE INDEX diagnostics_composite_1_fk ON diagnostics(coverage_part_id,collection_id);

CREATE INDEX diagnostics_composite_2_fk ON diagnostics(evidence_id,collection_id);

CREATE INDEX diagnostics_composite_3_fk ON diagnostics(key_observation_id,collection_id);

CREATE INDEX diagnostics_composite_4_fk ON diagnostics(claim_id,collection_id);

CREATE TRIGGER diagnostics_immutable_update BEFORE UPDATE ON diagnostics BEGIN SELECT RAISE(ABORT,'immutable record'); END;

CREATE TRIGGER diagnostics_immutable_delete BEFORE DELETE ON diagnostics BEGIN SELECT RAISE(ABORT,'immutable record'); END;

CREATE TRIGGER diagnostics_duplicate BEFORE INSERT ON diagnostics WHEN EXISTS(SELECT 1 FROM diagnostics WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'duplicate immutable identity'); END;

CREATE TABLE negative_justifications (
  id TEXT NOT NULL CHECK (id IS NULL OR (length(id)=36 AND length(CAST(id AS BLOB))=36 AND substr(id,9,1)='-' AND substr(id,14,1)='-' AND substr(id,19,1)='-' AND substr(id,24,1)='-' AND length(replace(id,'-',''))=32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*')),
  subject_id TEXT NOT NULL CHECK (subject_id IS NULL OR (length(subject_id)=36 AND length(CAST(subject_id AS BLOB))=36 AND substr(subject_id,9,1)='-' AND substr(subject_id,14,1)='-' AND substr(subject_id,19,1)='-' AND substr(subject_id,24,1)='-' AND length(replace(subject_id,'-',''))=32 AND replace(subject_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES claim_subjects(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  dimension TEXT NOT NULL CHECK (dimension IS NULL OR length(dimension)>0),
  authority_scope_id TEXT NOT NULL CHECK (authority_scope_id IS NULL OR (length(authority_scope_id)=36 AND length(CAST(authority_scope_id AS BLOB))=36 AND substr(authority_scope_id,9,1)='-' AND substr(authority_scope_id,14,1)='-' AND substr(authority_scope_id,19,1)='-' AND substr(authority_scope_id,24,1)='-' AND length(replace(authority_scope_id,'-',''))=32 AND replace(authority_scope_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES authority_scopes(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  evidence_id TEXT NOT NULL CHECK (evidence_id IS NULL OR (length(evidence_id)=36 AND length(CAST(evidence_id AS BLOB))=36 AND substr(evidence_id,9,1)='-' AND substr(evidence_id,14,1)='-' AND substr(evidence_id,19,1)='-' AND substr(evidence_id,24,1)='-' AND length(replace(evidence_id,'-',''))=32 AND replace(evidence_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES evidence_records(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  collection_id TEXT NOT NULL CHECK (collection_id IS NULL OR (length(collection_id)=36 AND length(CAST(collection_id AS BLOB))=36 AND substr(collection_id,9,1)='-' AND substr(collection_id,14,1)='-' AND substr(collection_id,19,1)='-' AND substr(collection_id,24,1)='-' AND length(replace(collection_id,'-',''))=32 AND replace(collection_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES collections(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  kind TEXT NOT NULL CHECK (kind IS NULL OR length(kind)>0),
  coverage_part_id TEXT CHECK (coverage_part_id IS NULL OR (length(coverage_part_id)=36 AND length(CAST(coverage_part_id AS BLOB))=36 AND substr(coverage_part_id,9,1)='-' AND substr(coverage_part_id,14,1)='-' AND substr(coverage_part_id,19,1)='-' AND substr(coverage_part_id,24,1)='-' AND length(replace(coverage_part_id,'-',''))=32 AND replace(coverage_part_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES coverage_parts(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  required_outcome TEXT CHECK (required_outcome IS NULL OR length(required_outcome)>0),
  capability_rule_id TEXT NOT NULL CHECK (capability_rule_id IS NULL OR (length(capability_rule_id)=36 AND length(CAST(capability_rule_id AS BLOB))=36 AND substr(capability_rule_id,9,1)='-' AND substr(capability_rule_id,14,1)='-' AND substr(capability_rule_id,19,1)='-' AND substr(capability_rule_id,24,1)='-' AND length(replace(capability_rule_id,'-',''))=32 AND replace(capability_rule_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES rule_versions(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  basis TEXT NOT NULL CHECK (basis IS NULL OR length(basis)>0),
  PRIMARY KEY (id),
  UNIQUE (id,subject_id,dimension,authority_scope_id,collection_id),
  CHECK ((kind='explicit' AND coverage_part_id IS NULL AND required_outcome IS NULL) OR (kind='exhaustive_omission' AND coverage_part_id IS NOT NULL AND required_outcome IS NOT NULL AND required_outcome='complete')),
  FOREIGN KEY (subject_id,dimension,authority_scope_id) REFERENCES claim_subjects(id,dimension,authority_scope_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  FOREIGN KEY (evidence_id,collection_id) REFERENCES evidence_records(id,collection_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  FOREIGN KEY (coverage_part_id,collection_id,required_outcome,dimension,authority_scope_id) REFERENCES coverage_parts(id,collection_id,outcome,dimension,authority_scope_id) ON UPDATE RESTRICT ON DELETE RESTRICT
) STRICT;

CREATE INDEX negative_justifications_subject_id_fk ON negative_justifications(subject_id);

CREATE INDEX negative_justifications_authority_scope_id_fk ON negative_justifications(authority_scope_id);

CREATE INDEX negative_justifications_evidence_id_fk ON negative_justifications(evidence_id);

CREATE INDEX negative_justifications_collection_id_fk ON negative_justifications(collection_id);

