CREATE TABLE reconciliation_decisions (
  id TEXT NOT NULL CHECK (id IS NULL OR (length(id)=36 AND length(CAST(id AS BLOB))=36 AND substr(id,9,1)='-' AND substr(id,14,1)='-' AND substr(id,19,1)='-' AND substr(id,24,1)='-' AND length(replace(id,'-',''))=32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*')),
  kind TEXT NOT NULL CHECK (kind IS NULL OR length(kind)>0),
  rule_id TEXT NOT NULL CHECK (rule_id IS NULL OR (length(rule_id)=36 AND length(CAST(rule_id AS BLOB))=36 AND substr(rule_id,9,1)='-' AND substr(rule_id,14,1)='-' AND substr(rule_id,19,1)='-' AND substr(rule_id,24,1)='-' AND length(replace(rule_id,'-',''))=32 AND replace(rule_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES rule_versions(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  ordering_rule_id TEXT CHECK (ordering_rule_id IS NULL OR (length(ordering_rule_id)=36 AND length(CAST(ordering_rule_id AS BLOB))=36 AND substr(ordering_rule_id,9,1)='-' AND substr(ordering_rule_id,14,1)='-' AND substr(ordering_rule_id,19,1)='-' AND substr(ordering_rule_id,24,1)='-' AND length(replace(ordering_rule_id,'-',''))=32 AND replace(ordering_rule_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES rule_versions(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  assessed_at INTEGER NOT NULL,
  reason TEXT NOT NULL CHECK (reason IS NULL OR length(reason)>0),
  collection_id TEXT CHECK (collection_id IS NULL OR (length(collection_id)=36 AND length(CAST(collection_id AS BLOB))=36 AND substr(collection_id,9,1)='-' AND substr(collection_id,14,1)='-' AND substr(collection_id,19,1)='-' AND substr(collection_id,24,1)='-' AND length(replace(collection_id,'-',''))=32 AND replace(collection_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES collections(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  PRIMARY KEY (id),
  CHECK (kind IN ('supersession','supersession_rejected','dispute')),
  CHECK (kind!='supersession' OR ordering_rule_id IS NOT NULL),
  FOREIGN KEY (id) REFERENCES decision_seals(decision_id) DEFERRABLE INITIALLY DEFERRED
) STRICT;

CREATE INDEX reconciliation_decisions_rule_id_fk ON reconciliation_decisions(rule_id);

CREATE INDEX reconciliation_decisions_ordering_rule_id_fk ON reconciliation_decisions(ordering_rule_id);

CREATE INDEX reconciliation_decisions_collection_id_fk ON reconciliation_decisions(collection_id);

CREATE TRIGGER reconciliation_decisions_immutable_update BEFORE UPDATE ON reconciliation_decisions BEGIN SELECT RAISE(ABORT,'immutable record'); END;

CREATE TRIGGER reconciliation_decisions_immutable_delete BEFORE DELETE ON reconciliation_decisions BEGIN SELECT RAISE(ABORT,'immutable record'); END;

CREATE TRIGGER reconciliation_decisions_duplicate BEFORE INSERT ON reconciliation_decisions WHEN EXISTS(SELECT 1 FROM reconciliation_decisions WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'duplicate immutable identity'); END;

CREATE TABLE decision_claims (
  decision_id TEXT NOT NULL CHECK (decision_id IS NULL OR (length(decision_id)=36 AND length(CAST(decision_id AS BLOB))=36 AND substr(decision_id,9,1)='-' AND substr(decision_id,14,1)='-' AND substr(decision_id,19,1)='-' AND substr(decision_id,24,1)='-' AND length(replace(decision_id,'-',''))=32 AND replace(decision_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES reconciliation_decisions(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  claim_id TEXT NOT NULL CHECK (claim_id IS NULL OR (length(claim_id)=36 AND length(CAST(claim_id AS BLOB))=36 AND substr(claim_id,9,1)='-' AND substr(claim_id,14,1)='-' AND substr(claim_id,19,1)='-' AND substr(claim_id,24,1)='-' AND length(replace(claim_id,'-',''))=32 AND replace(claim_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES claims(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  role TEXT NOT NULL CHECK (role IS NULL OR length(role)>0),
  PRIMARY KEY (decision_id,claim_id,role),
  CHECK (role IN ('older','replacement','identity_support','ordering_support','negative_support','conflicting'))
) STRICT;

CREATE INDEX decision_claims_decision_id_fk ON decision_claims(decision_id);

CREATE INDEX decision_claims_claim_id_fk ON decision_claims(claim_id);

CREATE TRIGGER decision_claims_immutable_update BEFORE UPDATE ON decision_claims BEGIN SELECT RAISE(ABORT,'immutable record'); END;

CREATE TRIGGER decision_claims_immutable_delete BEFORE DELETE ON decision_claims BEGIN SELECT RAISE(ABORT,'immutable record'); END;

CREATE TRIGGER decision_claims_duplicate BEFORE INSERT ON decision_claims WHEN EXISTS(SELECT 1 FROM decision_claims WHERE decision_id=NEW.decision_id AND claim_id=NEW.claim_id AND role=NEW.role) BEGIN SELECT RAISE(ABORT,'duplicate immutable identity'); END;

CREATE TABLE supersessions (
  older_claim_id TEXT NOT NULL CHECK (older_claim_id IS NULL OR (length(older_claim_id)=36 AND length(CAST(older_claim_id AS BLOB))=36 AND substr(older_claim_id,9,1)='-' AND substr(older_claim_id,14,1)='-' AND substr(older_claim_id,19,1)='-' AND substr(older_claim_id,24,1)='-' AND length(replace(older_claim_id,'-',''))=32 AND replace(older_claim_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES claims(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  replacement_claim_id TEXT NOT NULL CHECK (replacement_claim_id IS NULL OR (length(replacement_claim_id)=36 AND length(CAST(replacement_claim_id AS BLOB))=36 AND substr(replacement_claim_id,9,1)='-' AND substr(replacement_claim_id,14,1)='-' AND substr(replacement_claim_id,19,1)='-' AND substr(replacement_claim_id,24,1)='-' AND length(replace(replacement_claim_id,'-',''))=32 AND replace(replacement_claim_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES claims(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  dimension TEXT NOT NULL CHECK (dimension IS NULL OR length(dimension)>0),
  decision_id TEXT NOT NULL CHECK (decision_id IS NULL OR (length(decision_id)=36 AND length(CAST(decision_id AS BLOB))=36 AND substr(decision_id,9,1)='-' AND substr(decision_id,14,1)='-' AND substr(decision_id,19,1)='-' AND substr(decision_id,24,1)='-' AND length(replace(decision_id,'-',''))=32 AND replace(decision_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES reconciliation_decisions(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  PRIMARY KEY (older_claim_id,replacement_claim_id),
  CHECK (older_claim_id != replacement_claim_id),
  FOREIGN KEY (older_claim_id,dimension) REFERENCES claims(id,dimension) ON UPDATE RESTRICT ON DELETE RESTRICT,
  FOREIGN KEY (replacement_claim_id,dimension) REFERENCES claims(id,dimension) ON UPDATE RESTRICT ON DELETE RESTRICT
) STRICT;

CREATE INDEX supersessions_older_claim_id_fk ON supersessions(older_claim_id);

CREATE INDEX supersessions_replacement_claim_id_fk ON supersessions(replacement_claim_id);

CREATE INDEX supersessions_decision_id_fk ON supersessions(decision_id);

CREATE INDEX supersessions_composite_0_fk ON supersessions(older_claim_id,dimension);

CREATE INDEX supersessions_composite_1_fk ON supersessions(replacement_claim_id,dimension);

CREATE TRIGGER supersessions_immutable_update BEFORE UPDATE ON supersessions BEGIN SELECT RAISE(ABORT,'immutable record'); END;

CREATE TRIGGER supersessions_immutable_delete BEFORE DELETE ON supersessions BEGIN SELECT RAISE(ABORT,'immutable record'); END;

CREATE TRIGGER supersessions_duplicate BEFORE INSERT ON supersessions WHEN EXISTS(SELECT 1 FROM supersessions WHERE older_claim_id=NEW.older_claim_id AND replacement_claim_id=NEW.replacement_claim_id) BEGIN SELECT RAISE(ABORT,'duplicate immutable identity'); END;

CREATE TABLE decision_seals (
  decision_id TEXT NOT NULL CHECK (decision_id IS NULL OR (length(decision_id)=36 AND length(CAST(decision_id AS BLOB))=36 AND substr(decision_id,9,1)='-' AND substr(decision_id,14,1)='-' AND substr(decision_id,19,1)='-' AND substr(decision_id,24,1)='-' AND length(replace(decision_id,'-',''))=32 AND replace(decision_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES reconciliation_decisions(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  protocol TEXT NOT NULL CHECK (protocol IS NULL OR length(protocol)>0),
  content_digest BLOB NOT NULL CHECK (length(content_digest)=32),
  PRIMARY KEY (decision_id),
  CHECK (protocol='koine.decision.v1')
) STRICT;

CREATE INDEX decision_seals_decision_id_fk ON decision_seals(decision_id);

CREATE TRIGGER decision_seals_immutable_update BEFORE UPDATE ON decision_seals BEGIN SELECT RAISE(ABORT,'immutable record'); END;

CREATE TRIGGER decision_seals_immutable_delete BEFORE DELETE ON decision_seals BEGIN SELECT RAISE(ABORT,'immutable record'); END;

CREATE TRIGGER decision_seals_duplicate BEFORE INSERT ON decision_seals WHEN EXISTS(SELECT 1 FROM decision_seals WHERE decision_id=NEW.decision_id) BEGIN SELECT RAISE(ABORT,'duplicate immutable identity'); END;

CREATE TABLE launch_attempts (
  id TEXT NOT NULL CHECK (id IS NULL OR (length(id)=36 AND length(CAST(id AS BLOB))=36 AND substr(id,9,1)='-' AND substr(id,14,1)='-' AND substr(id,19,1)='-' AND substr(id,24,1)='-' AND length(replace(id,'-',''))=32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*')),
  target_id TEXT NOT NULL CHECK (target_id IS NULL OR (length(target_id)=36 AND length(CAST(target_id AS BLOB))=36 AND substr(target_id,9,1)='-' AND substr(target_id,14,1)='-' AND substr(target_id,19,1)='-' AND substr(target_id,24,1)='-' AND length(replace(target_id,'-',''))=32 AND replace(target_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES launch_targets(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  created_at INTEGER NOT NULL,
  intent_reason TEXT NOT NULL CHECK (intent_reason IS NULL OR length(intent_reason)>0),
  PRIMARY KEY (id)
) STRICT;

CREATE INDEX launch_attempts_target_id_fk ON launch_attempts(target_id);

CREATE TRIGGER launch_attempts_immutable_update BEFORE UPDATE ON launch_attempts BEGIN SELECT RAISE(ABORT,'immutable record'); END;

CREATE TRIGGER launch_attempts_immutable_delete BEFORE DELETE ON launch_attempts BEGIN SELECT RAISE(ABORT,'immutable record'); END;

CREATE TRIGGER launch_attempts_duplicate BEFORE INSERT ON launch_attempts WHEN EXISTS(SELECT 1 FROM launch_attempts WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'duplicate immutable identity'); END;

CREATE TABLE handoff_records (
  id TEXT NOT NULL CHECK (id IS NULL OR (length(id)=36 AND length(CAST(id AS BLOB))=36 AND substr(id,9,1)='-' AND substr(id,14,1)='-' AND substr(id,19,1)='-' AND substr(id,24,1)='-' AND length(replace(id,'-',''))=32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*')),
  attempt_id TEXT NOT NULL CHECK (attempt_id IS NULL OR (length(attempt_id)=36 AND length(CAST(attempt_id AS BLOB))=36 AND substr(attempt_id,9,1)='-' AND substr(attempt_id,14,1)='-' AND substr(attempt_id,19,1)='-' AND substr(attempt_id,24,1)='-' AND length(replace(attempt_id,'-',''))=32 AND replace(attempt_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES launch_attempts(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  item_key TEXT NOT NULL CHECK (item_key IS NULL OR length(item_key)>0),
  recorded_at INTEGER NOT NULL,
  transport_rule_id TEXT NOT NULL CHECK (transport_rule_id IS NULL OR (length(transport_rule_id)=36 AND length(CAST(transport_rule_id AS BLOB))=36 AND substr(transport_rule_id,9,1)='-' AND substr(transport_rule_id,14,1)='-' AND substr(transport_rule_id,19,1)='-' AND substr(transport_rule_id,24,1)='-' AND length(replace(transport_rule_id,'-',''))=32 AND replace(transport_rule_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES rule_versions(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  boundary TEXT NOT NULL CHECK (boundary IS NULL OR length(boundary)>0),
  issuance TEXT NOT NULL CHECK (issuance IS NULL OR length(issuance)>0),
  disposition TEXT NOT NULL CHECK (disposition IS NULL OR length(disposition)>0),
  exit_status INTEGER,
  termination_signal INTEGER,
  reason TEXT CHECK (reason IS NULL OR length(reason)>0),
  PRIMARY KEY (id),
  UNIQUE (attempt_id,item_key),
  CHECK (issuance IN ('issued','not_issued','unknown')),
  CHECK (disposition IN ('pending','accepted','failed','inconclusive','not_requested')),
  CHECK ((disposition NOT IN ('pending','accepted') OR issuance='issued') AND (disposition!='not_requested' OR issuance='not_issued') AND (disposition NOT IN ('failed','inconclusive','not_requested') OR reason IS NOT NULL)),
  CHECK ((exit_status IS NULL OR (exit_status>=0 AND termination_signal IS NULL AND disposition IN ('accepted','failed','inconclusive'))) AND (termination_signal IS NULL OR (termination_signal>0 AND exit_status IS NULL AND disposition IN ('accepted','failed','inconclusive'))))
) STRICT;

CREATE INDEX handoff_records_attempt_id_fk ON handoff_records(attempt_id);

CREATE INDEX handoff_records_transport_rule_id_fk ON handoff_records(transport_rule_id);

CREATE TRIGGER handoff_records_immutable_update BEFORE UPDATE ON handoff_records BEGIN SELECT RAISE(ABORT,'immutable record'); END;

CREATE TRIGGER handoff_records_immutable_delete BEFORE DELETE ON handoff_records BEGIN SELECT RAISE(ABORT,'immutable record'); END;

CREATE TRIGGER handoff_records_duplicate BEFORE INSERT ON handoff_records WHEN EXISTS(SELECT 1 FROM handoff_records WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'duplicate immutable identity'); END;

CREATE TABLE process_observations (
  id TEXT NOT NULL CHECK (id IS NULL OR (length(id)=36 AND length(CAST(id AS BLOB))=36 AND substr(id,9,1)='-' AND substr(id,14,1)='-' AND substr(id,19,1)='-' AND substr(id,24,1)='-' AND length(replace(id,'-',''))=32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*')),
  attempt_id TEXT NOT NULL CHECK (attempt_id IS NULL OR (length(attempt_id)=36 AND length(CAST(attempt_id AS BLOB))=36 AND substr(attempt_id,9,1)='-' AND substr(attempt_id,14,1)='-' AND substr(attempt_id,19,1)='-' AND substr(attempt_id,24,1)='-' AND length(replace(attempt_id,'-',''))=32 AND replace(attempt_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES launch_attempts(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  item_key TEXT NOT NULL CHECK (item_key IS NULL OR length(item_key)>0),
  observed_at INTEGER NOT NULL,
  method_rule_id TEXT NOT NULL CHECK (method_rule_id IS NULL OR (length(method_rule_id)=36 AND length(CAST(method_rule_id AS BLOB))=36 AND substr(method_rule_id,9,1)='-' AND substr(method_rule_id,14,1)='-' AND substr(method_rule_id,19,1)='-' AND substr(method_rule_id,24,1)='-' AND length(replace(method_rule_id,'-',''))=32 AND replace(method_rule_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES rule_versions(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  observer_epoch TEXT NOT NULL CHECK (observer_epoch IS NULL OR (length(observer_epoch)=36 AND length(CAST(observer_epoch AS BLOB))=36 AND substr(observer_epoch,9,1)='-' AND substr(observer_epoch,14,1)='-' AND substr(observer_epoch,19,1)='-' AND substr(observer_epoch,24,1)='-' AND length(replace(observer_epoch,'-',''))=32 AND replace(observer_epoch,'-','') NOT GLOB '*[^0-9a-f]*')),
  state TEXT NOT NULL CHECK (state IS NULL OR length(state)>0),
  identity_token BLOB,
  identity_basis TEXT CHECK (identity_basis IS NULL OR length(identity_basis)>0),
  pid INTEGER,
  prior_observed_id TEXT CHECK (prior_observed_id IS NULL OR (length(prior_observed_id)=36 AND length(CAST(prior_observed_id AS BLOB))=36 AND substr(prior_observed_id,9,1)='-' AND substr(prior_observed_id,14,1)='-' AND substr(prior_observed_id,19,1)='-' AND substr(prior_observed_id,24,1)='-' AND length(replace(prior_observed_id,'-',''))=32 AND replace(prior_observed_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES process_observations(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  prior_state TEXT CHECK (prior_state IS NULL OR length(prior_state)>0),
  reason TEXT CHECK (reason IS NULL OR length(reason)>0),
  PRIMARY KEY (id),
  UNIQUE (attempt_id,item_key),
  UNIQUE (id,attempt_id,state),
  CHECK (state IN ('observed','inconclusive','exited')),
  CHECK ((state IN ('observed','exited') AND identity_token IS NOT NULL AND length(identity_token)>0 AND identity_basis IS NOT NULL) OR (state='inconclusive' AND reason IS NOT NULL AND identity_token IS NULL AND identity_basis IS NULL AND pid IS NULL)),
  CHECK (pid IS NULL OR pid>0),
  CHECK ((prior_observed_id IS NULL AND prior_state IS NULL) OR (prior_observed_id IS NOT NULL AND prior_state IS NOT NULL AND prior_state='observed' AND prior_observed_id!=id)),
  CHECK (state!='exited' OR prior_observed_id IS NOT NULL),
  FOREIGN KEY (prior_observed_id,attempt_id,prior_state) REFERENCES process_observations(id,attempt_id,state) ON UPDATE RESTRICT ON DELETE RESTRICT
) STRICT;

CREATE INDEX process_observations_attempt_id_fk ON process_observations(attempt_id);

CREATE INDEX process_observations_method_rule_id_fk ON process_observations(method_rule_id);

CREATE INDEX process_observations_prior_observed_id_fk ON process_observations(prior_observed_id);

CREATE INDEX process_observations_composite_0_fk ON process_observations(prior_observed_id,attempt_id,prior_state);

CREATE TRIGGER process_observations_immutable_update BEFORE UPDATE ON process_observations BEGIN SELECT RAISE(ABORT,'immutable record'); END;

CREATE TRIGGER process_observations_immutable_delete BEFORE DELETE ON process_observations BEGIN SELECT RAISE(ABORT,'immutable record'); END;

CREATE TRIGGER process_observations_duplicate BEFORE INSERT ON process_observations WHEN EXISTS(SELECT 1 FROM process_observations WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'duplicate immutable identity'); END;

CREATE TABLE claim_subjects (
  id TEXT NOT NULL CHECK (id IS NULL OR (length(id)=36 AND length(CAST(id AS BLOB))=36 AND substr(id,9,1)='-' AND substr(id,14,1)='-' AND substr(id,19,1)='-' AND substr(id,24,1)='-' AND length(replace(id,'-',''))=32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*')),
  dimension TEXT NOT NULL CHECK (dimension IS NULL OR length(dimension)>0),
  authority_scope_id TEXT NOT NULL CHECK (authority_scope_id IS NULL OR (length(authority_scope_id)=36 AND length(CAST(authority_scope_id AS BLOB))=36 AND substr(authority_scope_id,9,1)='-' AND substr(authority_scope_id,14,1)='-' AND substr(authority_scope_id,19,1)='-' AND substr(authority_scope_id,24,1)='-' AND length(replace(authority_scope_id,'-',''))=32 AND replace(authority_scope_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES authority_scopes(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
