  entry_id TEXT CHECK (entry_id IS NULL OR (length(entry_id)=36 AND length(CAST(entry_id AS BLOB))=36 AND substr(entry_id,9,1)='-' AND substr(entry_id,14,1)='-' AND substr(entry_id,19,1)='-' AND substr(entry_id,24,1)='-' AND length(replace(entry_id,'-',''))=32 AND replace(entry_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES source_entries(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  entitlement_id TEXT CHECK (entitlement_id IS NULL OR (length(entitlement_id)=36 AND length(CAST(entitlement_id AS BLOB))=36 AND substr(entitlement_id,9,1)='-' AND substr(entitlement_id,14,1)='-' AND substr(entitlement_id,19,1)='-' AND substr(entitlement_id,24,1)='-' AND length(replace(entitlement_id,'-',''))=32 AND replace(entitlement_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES entitlements(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  installation_id TEXT CHECK (installation_id IS NULL OR (length(installation_id)=36 AND length(CAST(installation_id AS BLOB))=36 AND substr(installation_id,9,1)='-' AND substr(installation_id,14,1)='-' AND substr(installation_id,19,1)='-' AND substr(installation_id,24,1)='-' AND length(replace(installation_id,'-',''))=32 AND replace(installation_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES installations(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  target_id TEXT CHECK (target_id IS NULL OR (length(target_id)=36 AND length(CAST(target_id AS BLOB))=36 AND substr(target_id,9,1)='-' AND substr(target_id,14,1)='-' AND substr(target_id,19,1)='-' AND substr(target_id,24,1)='-' AND length(replace(target_id,'-',''))=32 AND replace(target_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES launch_targets(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  game_link_id TEXT CHECK (game_link_id IS NULL OR (length(game_link_id)=36 AND length(CAST(game_link_id AS BLOB))=36 AND substr(game_link_id,9,1)='-' AND substr(game_link_id,14,1)='-' AND substr(game_link_id,19,1)='-' AND substr(game_link_id,24,1)='-' AND length(replace(game_link_id,'-',''))=32 AND replace(game_link_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES game_links(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  equivalence_id TEXT CHECK (equivalence_id IS NULL OR (length(equivalence_id)=36 AND length(CAST(equivalence_id AS BLOB))=36 AND substr(equivalence_id,9,1)='-' AND substr(equivalence_id,14,1)='-' AND substr(equivalence_id,19,1)='-' AND substr(equivalence_id,24,1)='-' AND length(replace(equivalence_id,'-',''))=32 AND replace(equivalence_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES entry_equivalences(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  context_equivalence_id TEXT CHECK (context_equivalence_id IS NULL OR (length(context_equivalence_id)=36 AND length(CAST(context_equivalence_id AS BLOB))=36 AND substr(context_equivalence_id,9,1)='-' AND substr(context_equivalence_id,14,1)='-' AND substr(context_equivalence_id,19,1)='-' AND substr(context_equivalence_id,24,1)='-' AND length(replace(context_equivalence_id,'-',''))=32 AND replace(context_equivalence_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES context_equivalences(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  target_installation_link_id TEXT CHECK (target_installation_link_id IS NULL OR (length(target_installation_link_id)=36 AND length(CAST(target_installation_link_id AS BLOB))=36 AND substr(target_installation_link_id,9,1)='-' AND substr(target_installation_link_id,14,1)='-' AND substr(target_installation_link_id,19,1)='-' AND substr(target_installation_link_id,24,1)='-' AND length(replace(target_installation_link_id,'-',''))=32 AND replace(target_installation_link_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES target_installation_links(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  PRIMARY KEY (id),
  UNIQUE (id,dimension,authority_scope_id),
  CHECK ((dimension='game_label' AND game_id IS NOT NULL AND entry_id IS NULL AND entitlement_id IS NULL AND installation_id IS NULL AND target_id IS NULL AND game_link_id IS NULL AND equivalence_id IS NULL AND context_equivalence_id IS NULL AND target_installation_link_id IS NULL) OR (dimension='entry_title' AND game_id IS NULL AND entry_id IS NOT NULL AND entitlement_id IS NULL AND installation_id IS NULL AND target_id IS NULL AND game_link_id IS NULL AND equivalence_id IS NULL AND context_equivalence_id IS NULL AND target_installation_link_id IS NULL) OR (dimension='entry_edition' AND game_id IS NULL AND entry_id IS NOT NULL AND entitlement_id IS NULL AND installation_id IS NULL AND target_id IS NULL AND game_link_id IS NULL AND equivalence_id IS NULL AND context_equivalence_id IS NULL AND target_installation_link_id IS NULL) OR (dimension='manual_visibility' AND game_id IS NULL AND entry_id IS NOT NULL AND entitlement_id IS NULL AND installation_id IS NULL AND target_id IS NULL AND game_link_id IS NULL AND equivalence_id IS NULL AND context_equivalence_id IS NULL AND target_installation_link_id IS NULL) OR (dimension='access' AND game_id IS NULL AND entry_id IS NULL AND entitlement_id IS NOT NULL AND installation_id IS NULL AND target_id IS NULL AND game_link_id IS NULL AND equivalence_id IS NULL AND context_equivalence_id IS NULL AND target_installation_link_id IS NULL) OR (dimension='presence' AND game_id IS NULL AND entry_id IS NULL AND entitlement_id IS NULL AND installation_id IS NOT NULL AND target_id IS NULL AND game_link_id IS NULL AND equivalence_id IS NULL AND context_equivalence_id IS NULL AND target_installation_link_id IS NULL) OR (dimension='completion' AND game_id IS NULL AND entry_id IS NULL AND entitlement_id IS NULL AND installation_id IS NOT NULL AND target_id IS NULL AND game_link_id IS NULL AND equivalence_id IS NULL AND context_equivalence_id IS NULL AND target_installation_link_id IS NULL) OR (dimension='location' AND game_id IS NULL AND entry_id IS NULL AND entitlement_id IS NULL AND installation_id IS NOT NULL AND target_id IS NULL AND game_link_id IS NULL AND equivalence_id IS NULL AND context_equivalence_id IS NULL AND target_installation_link_id IS NULL) OR (dimension='handoff_capability' AND game_id IS NULL AND entry_id IS NULL AND entitlement_id IS NULL AND installation_id IS NULL AND target_id IS NOT NULL AND game_link_id IS NULL AND equivalence_id IS NULL AND context_equivalence_id IS NULL AND target_installation_link_id IS NULL) OR (dimension='target_installation' AND game_id IS NULL AND entry_id IS NULL AND entitlement_id IS NULL AND installation_id IS NULL AND target_id IS NULL AND game_link_id IS NULL AND equivalence_id IS NULL AND context_equivalence_id IS NULL AND target_installation_link_id IS NOT NULL) OR (dimension='game_link' AND game_id IS NULL AND entry_id IS NULL AND entitlement_id IS NULL AND installation_id IS NULL AND target_id IS NULL AND game_link_id IS NOT NULL AND equivalence_id IS NULL AND context_equivalence_id IS NULL AND target_installation_link_id IS NULL) OR (dimension='entry_equivalence' AND game_id IS NULL AND entry_id IS NULL AND entitlement_id IS NULL AND installation_id IS NULL AND target_id IS NULL AND game_link_id IS NULL AND equivalence_id IS NOT NULL AND context_equivalence_id IS NULL AND target_installation_link_id IS NULL) OR (dimension='context_equivalence' AND game_id IS NULL AND entry_id IS NULL AND entitlement_id IS NULL AND installation_id IS NULL AND target_id IS NULL AND game_link_id IS NULL AND equivalence_id IS NULL AND context_equivalence_id IS NOT NULL AND target_installation_link_id IS NULL)),
  FOREIGN KEY (entitlement_id,authority_scope_id) REFERENCES entitlements(id,authority_scope_id) ON UPDATE RESTRICT ON DELETE RESTRICT
) STRICT;

