CREATE TABLE claims (
  id TEXT NOT NULL CHECK (id IS NULL OR (length(id)=36 AND length(CAST(id AS BLOB))=36 AND substr(id,9,1)='-' AND substr(id,14,1)='-' AND substr(id,19,1)='-' AND substr(id,24,1)='-' AND length(replace(id,'-',''))=32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*')),
  subject_id TEXT NOT NULL CHECK (subject_id IS NULL OR (length(subject_id)=36 AND length(CAST(subject_id AS BLOB))=36 AND substr(subject_id,9,1)='-' AND substr(subject_id,14,1)='-' AND substr(subject_id,19,1)='-' AND substr(subject_id,24,1)='-' AND length(replace(subject_id,'-',''))=32 AND replace(subject_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES claim_subjects(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  dimension TEXT NOT NULL CHECK (dimension IS NULL OR length(dimension)>0),
  authority_scope_id TEXT NOT NULL CHECK (authority_scope_id IS NULL OR (length(authority_scope_id)=36 AND length(CAST(authority_scope_id AS BLOB))=36 AND substr(authority_scope_id,9,1)='-' AND substr(authority_scope_id,14,1)='-' AND substr(authority_scope_id,19,1)='-' AND substr(authority_scope_id,24,1)='-' AND length(replace(authority_scope_id,'-',''))=32 AND replace(authority_scope_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES authority_scopes(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  evidence_id TEXT NOT NULL CHECK (evidence_id IS NULL OR (length(evidence_id)=36 AND length(CAST(evidence_id AS BLOB))=36 AND substr(evidence_id,9,1)='-' AND substr(evidence_id,14,1)='-' AND substr(evidence_id,19,1)='-' AND substr(evidence_id,24,1)='-' AND length(replace(evidence_id,'-',''))=32 AND replace(evidence_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES evidence_records(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  collection_id TEXT NOT NULL CHECK (collection_id IS NULL OR (length(collection_id)=36 AND length(CAST(collection_id AS BLOB))=36 AND substr(collection_id,9,1)='-' AND substr(collection_id,14,1)='-' AND substr(collection_id,19,1)='-' AND substr(collection_id,24,1)='-' AND length(replace(collection_id,'-',''))=32 AND replace(collection_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES collections(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  knowledge TEXT NOT NULL CHECK (knowledge IS NULL OR length(knowledge)>0),
  value_text TEXT CHECK (value_text IS NULL OR length(value_text)>0),
  value_bytes BLOB,
  access_kind TEXT CHECK (access_kind IS NULL OR length(access_kind)>0),
  reason TEXT CHECK (reason IS NULL OR length(reason)>0),
  basis_code TEXT NOT NULL CHECK (basis_code IS NULL OR length(basis_code)>0),
  negative_justification_id TEXT CHECK (negative_justification_id IS NULL OR (length(negative_justification_id)=36 AND length(CAST(negative_justification_id AS BLOB))=36 AND substr(negative_justification_id,9,1)='-' AND substr(negative_justification_id,14,1)='-' AND substr(negative_justification_id,19,1)='-' AND substr(negative_justification_id,24,1)='-' AND length(replace(negative_justification_id,'-',''))=32 AND replace(negative_justification_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES negative_justifications(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  coverage_part_id TEXT CHECK (coverage_part_id IS NULL OR (length(coverage_part_id)=36 AND length(CAST(coverage_part_id AS BLOB))=36 AND substr(coverage_part_id,9,1)='-' AND substr(coverage_part_id,14,1)='-' AND substr(coverage_part_id,19,1)='-' AND substr(coverage_part_id,24,1)='-' AND length(replace(coverage_part_id,'-',''))=32 AND replace(coverage_part_id,'-','') NOT GLOB '*[^0-9a-f]*')) REFERENCES coverage_parts(id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  PRIMARY KEY (id),
  UNIQUE (id,collection_id),
  UNIQUE (id,dimension),
  UNIQUE (id,subject_id,dimension,authority_scope_id),
  CHECK (dimension IN ('game_label','entry_title','entry_edition','manual_visibility','access','presence','completion','location','handoff_capability','target_installation','game_link','entry_equivalence','context_equivalence')),
  CHECK (knowledge IN ('observed','confirmed_negative','unknown')),
  CHECK ((knowledge='unknown' AND reason IS NOT NULL AND value_text IS NULL AND value_bytes IS NULL AND access_kind IS NULL AND negative_justification_id IS NULL) OR (knowledge='observed' AND negative_justification_id IS NULL AND ((dimension='game_label' AND value_text IS NOT NULL AND value_bytes IS NULL) OR (dimension='entry_title' AND value_text IS NOT NULL AND value_bytes IS NULL) OR (dimension='entry_edition' AND value_text IS NOT NULL AND value_bytes IS NULL) OR (dimension='manual_visibility' AND value_text IS NOT NULL AND value_text IN ('visible','hidden') AND value_bytes IS NULL) OR (dimension='access' AND value_text IS NOT NULL AND value_text IN ('accessible') AND value_bytes IS NULL) OR (dimension='presence' AND value_text IS NOT NULL AND value_text IN ('present') AND value_bytes IS NULL) OR (dimension='completion' AND value_text IS NOT NULL AND value_text IN ('complete','incomplete') AND value_bytes IS NULL) OR (dimension='location' AND value_text IS NULL AND value_bytes IS NOT NULL AND length(value_bytes)>0) OR (dimension='handoff_capability' AND value_text IS NOT NULL AND value_text IN ('supported','unavailable') AND value_bytes IS NULL) OR (dimension='target_installation' AND value_text IS NOT NULL AND value_text IN ('linked','unlinked') AND value_bytes IS NULL) OR (dimension='game_link' AND value_text IS NOT NULL AND value_text IN ('linked','unlinked') AND value_bytes IS NULL) OR (dimension='entry_equivalence' AND value_text IS NOT NULL AND value_text IN ('equivalent','different') AND value_bytes IS NULL) OR (dimension='context_equivalence' AND value_text IS NOT NULL AND value_text IN ('equivalent','different') AND value_bytes IS NULL))) OR (knowledge='confirmed_negative' AND negative_justification_id IS NOT NULL AND value_bytes IS NULL AND value_text IS NOT NULL AND ((dimension='access' AND value_text='inaccessible') OR (dimension='presence' AND value_text='absent')))),
  CHECK (access_kind IS NULL OR (knowledge='observed' AND dimension='access' AND value_text='accessible')),
  FOREIGN KEY (subject_id,dimension,authority_scope_id) REFERENCES claim_subjects(id,dimension,authority_scope_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  FOREIGN KEY (evidence_id,collection_id) REFERENCES evidence_records(id,collection_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  FOREIGN KEY (coverage_part_id,collection_id,dimension,authority_scope_id) REFERENCES coverage_parts(id,collection_id,dimension,authority_scope_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  FOREIGN KEY (negative_justification_id,subject_id,dimension,authority_scope_id,collection_id) REFERENCES negative_justifications(id,subject_id,dimension,authority_scope_id,collection_id) ON UPDATE RESTRICT ON DELETE RESTRICT
) STRICT;

