CREATE TABLE database_identity (
  id TEXT NOT NULL CHECK (id IS NULL OR (length(id)=36 AND length(CAST(id AS BLOB))=36 AND substr(id,9,1)='-' AND substr(id,14,1)='-' AND substr(id,19,1)='-' AND substr(id,24,1)='-' AND length(replace(id,'-',''))=32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*')),
  family TEXT NOT NULL CHECK (family IS NULL OR length(family)>0),
  initial_version INTEGER NOT NULL,
  PRIMARY KEY (id),
  UNIQUE (family),
  CHECK (family='koine.offline.foundation' AND initial_version=1)
) STRICT;

