CREATE TABLE migration_history (
  id TEXT NOT NULL CHECK (id IS NULL OR (length(id)=36 AND length(CAST(id AS BLOB))=36 AND substr(id,9,1)='-' AND substr(id,14,1)='-' AND substr(id,19,1)='-' AND substr(id,24,1)='-' AND length(replace(id,'-',''))=32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*')),
  migration_id TEXT NOT NULL CHECK (migration_id IS NULL OR length(migration_id)>0),
  source_version INTEGER NOT NULL,
  target_version INTEGER NOT NULL,
  artifact_digest BLOB NOT NULL CHECK (length(artifact_digest)=32),
  build TEXT NOT NULL CHECK (build IS NULL OR length(build)>0),
  applied_at INTEGER NOT NULL,
  PRIMARY KEY (id),
  UNIQUE (source_version),
  UNIQUE (target_version),
  CHECK (migration_id='bootstrap.v1' AND source_version=0 AND target_version=1)
) STRICT;

