CREATE UNIQUE INDEX scope_library ON identity_scopes(namespace,library_context_id) WHERE resolution='resolved' AND scope_kind='library';

CREATE UNIQUE INDEX scope_provisional ON identity_scopes(provisional_token) WHERE resolution='provisional';

CREATE UNIQUE INDEX coverage_root ON coverage_parts(coverage_id) WHERE parent_part_id IS NULL;

CREATE UNIQUE INDEX subject_game_id ON claim_subjects(game_id,dimension,authority_scope_id) WHERE game_id IS NOT NULL;

CREATE UNIQUE INDEX subject_entry_id ON claim_subjects(entry_id,dimension,authority_scope_id) WHERE entry_id IS NOT NULL;

CREATE UNIQUE INDEX subject_entitlement_id ON claim_subjects(entitlement_id,dimension,authority_scope_id) WHERE entitlement_id IS NOT NULL;

CREATE UNIQUE INDEX subject_installation_id ON claim_subjects(installation_id,dimension,authority_scope_id) WHERE installation_id IS NOT NULL;

CREATE UNIQUE INDEX subject_target_id ON claim_subjects(target_id,dimension,authority_scope_id) WHERE target_id IS NOT NULL;

CREATE UNIQUE INDEX subject_game_link_id ON claim_subjects(game_link_id,dimension,authority_scope_id) WHERE game_link_id IS NOT NULL;

CREATE UNIQUE INDEX subject_equivalence_id ON claim_subjects(equivalence_id,dimension,authority_scope_id) WHERE equivalence_id IS NOT NULL;

CREATE UNIQUE INDEX subject_context_equivalence_id ON claim_subjects(context_equivalence_id,dimension,authority_scope_id) WHERE context_equivalence_id IS NOT NULL;

CREATE UNIQUE INDEX subject_target_installation_link_id ON claim_subjects(target_installation_link_id,dimension,authority_scope_id) WHERE target_installation_link_id IS NOT NULL;

CREATE TRIGGER entry_key_observations_closed BEFORE INSERT ON entry_key_observations WHEN EXISTS(SELECT 1 FROM collection_closures WHERE collection_id=NEW.collection_id) BEGIN SELECT RAISE(ABORT,'closed collection'); END;

CREATE TRIGGER requested_units_closed BEFORE INSERT ON requested_units WHEN EXISTS(SELECT 1 FROM collection_closures WHERE collection_id=NEW.collection_id) BEGIN SELECT RAISE(ABORT,'closed collection'); END;

CREATE TRIGGER coverage_results_closed BEFORE INSERT ON coverage_results WHEN EXISTS(SELECT 1 FROM collection_closures WHERE collection_id=NEW.collection_id) BEGIN SELECT RAISE(ABORT,'closed collection'); END;

CREATE TRIGGER coverage_parts_closed BEFORE INSERT ON coverage_parts WHEN EXISTS(SELECT 1 FROM collection_closures WHERE collection_id=NEW.collection_id) BEGIN SELECT RAISE(ABORT,'closed collection'); END;

CREATE TRIGGER evidence_records_closed BEFORE INSERT ON evidence_records WHEN EXISTS(SELECT 1 FROM collection_closures WHERE collection_id=NEW.collection_id) BEGIN SELECT RAISE(ABORT,'closed collection'); END;

CREATE TRIGGER diagnostics_closed BEFORE INSERT ON diagnostics WHEN EXISTS(SELECT 1 FROM collection_closures WHERE collection_id=NEW.collection_id) BEGIN SELECT RAISE(ABORT,'closed collection'); END;

CREATE TRIGGER negative_justifications_closed BEFORE INSERT ON negative_justifications WHEN EXISTS(SELECT 1 FROM collection_closures WHERE collection_id=NEW.collection_id) BEGIN SELECT RAISE(ABORT,'closed collection'); END;

CREATE TRIGGER reconciliation_decisions_closed BEFORE INSERT ON reconciliation_decisions WHEN EXISTS(SELECT 1 FROM collection_closures WHERE collection_id=NEW.collection_id) BEGIN SELECT RAISE(ABORT,'closed collection'); END;

CREATE TRIGGER claims_closed BEFORE INSERT ON claims WHEN EXISTS(SELECT 1 FROM collection_closures WHERE collection_id=NEW.collection_id) BEGIN SELECT RAISE(ABORT,'closed collection'); END;

CREATE TRIGGER decision_claims_sealed BEFORE INSERT ON decision_claims WHEN EXISTS(SELECT 1 FROM decision_seals WHERE decision_id=NEW.decision_id) BEGIN SELECT RAISE(ABORT,'sealed decision'); END;

CREATE TRIGGER supersessions_sealed BEFORE INSERT ON supersessions WHEN EXISTS(SELECT 1 FROM decision_seals WHERE decision_id=NEW.decision_id) BEGIN SELECT RAISE(ABORT,'sealed decision'); END;

CREATE TRIGGER supersession_cycle BEFORE INSERT ON supersessions WHEN EXISTS(
 WITH RECURSIVE reachable(id) AS (VALUES(NEW.replacement_claim_id) UNION SELECT s.replacement_claim_id FROM supersessions s JOIN reachable r ON s.older_claim_id=r.id)
 SELECT 1 FROM reachable WHERE id=NEW.older_claim_id
) BEGIN SELECT RAISE(ABORT,'supersession cycle'); END;

CREATE TRIGGER coverage_cycle BEFORE INSERT ON coverage_parts WHEN NEW.parent_part_id IS NOT NULL AND (
 NOT EXISTS(SELECT 1 FROM coverage_parts WHERE id=NEW.parent_part_id) OR EXISTS(
 WITH RECURSIVE ancestors(id,path,cycle) AS (
 SELECT NEW.parent_part_id,'|'||NEW.parent_part_id||'|',0
 UNION ALL SELECT p.parent_part_id,a.path||p.parent_part_id||'|',instr(a.path,'|'||p.parent_part_id||'|')>0
 FROM coverage_parts p JOIN ancestors a ON p.id=a.id WHERE p.parent_part_id IS NOT NULL AND a.cycle=0)
 SELECT 1 FROM ancestors WHERE id=NEW.id OR cycle=1)) BEGIN SELECT RAISE(ABORT,'coverage parent'); END;

CREATE INDEX claims_retrieval ON claims(subject_id,evidence_id);

CREATE INDEX evidence_records_retrieval ON evidence_records(collection_id,collected_at);

CREATE INDEX supersessions_retrieval ON supersessions(replacement_claim_id,older_claim_id);

CREATE INDEX handoff_records_retrieval ON handoff_records(attempt_id,recorded_at);

CREATE INDEX process_observations_retrieval ON process_observations(attempt_id,observed_at);
